using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>
/// Exercises HttpPaymentGateway against a stubbed HTTP handler that plays the part of the
/// provider's REST API, proving both what we send on the wire and how we interpret what
/// comes back, including the provider's refusal path.
/// </summary>
public sealed class HttpPaymentGatewayTests
{
    [Fact]
    public async Task Sends_the_reference_amount_and_currency_the_provider_expects()
    {
        HttpRequestMessage? capturedRequest = null;
        string? capturedBody = null;

        var handler = new StubHttpMessageHandler((request, body) =>
        {
            capturedRequest = request;
            capturedBody = body;
            return new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = JsonContent("""{"status":"approved"}""")
            };
        });

        var gateway = new Infrastructure.HttpPaymentGateway(CreateClient(handler));

        await gateway.AuthorizeAsync("ORD-1", new Money(42.50m, "eur"), CancellationToken.None);

        Assert.Equal(HttpMethod.Post, capturedRequest!.Method);
        Assert.Equal("/v1/authorizations", capturedRequest.RequestUri!.PathAndQuery);

        using var payload = JsonDocument.Parse(capturedBody!);
        Assert.Equal("ORD-1", payload.RootElement.GetProperty("reference").GetString());
        Assert.Equal(42.50m, payload.RootElement.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", payload.RootElement.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_response_is_read_back_as_approved()
    {
        var handler = new StubHttpMessageHandler((_, _) => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = JsonContent("""{"status":"approved"}""")
        });
        var gateway = new Infrastructure.HttpPaymentGateway(CreateClient(handler));

        var outcome = await gateway.AuthorizeAsync("ORD-2", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_response_is_read_back_as_declined()
    {
        var handler = new StubHttpMessageHandler((_, _) => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = JsonContent("""{"status":"declined"}""")
        });
        var gateway = new Infrastructure.HttpPaymentGateway(CreateClient(handler));

        var outcome = await gateway.AuthorizeAsync("ORD-3", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unrecognized_status_is_treated_as_declined()
    {
        var handler = new StubHttpMessageHandler((_, _) => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = JsonContent("""{"status":"pending"}""")
        });
        var gateway = new Infrastructure.HttpPaymentGateway(CreateClient(handler));

        var outcome = await gateway.AuthorizeAsync("ORD-4", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_response_means_the_provider_refused_the_payment_outright()
    {
        var handler = new StubHttpMessageHandler((_, _) => new HttpResponseMessage(HttpStatusCode.PaymentRequired));
        var gateway = new Infrastructure.HttpPaymentGateway(CreateClient(handler));

        var outcome = await gateway.AuthorizeAsync("ORD-5", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unexpected_server_error_is_not_swallowed_as_a_decline()
    {
        var handler = new StubHttpMessageHandler((_, _) => new HttpResponseMessage(HttpStatusCode.InternalServerError));
        var gateway = new Infrastructure.HttpPaymentGateway(CreateClient(handler));

        await Assert.ThrowsAsync<HttpRequestException>(
            () => gateway.AuthorizeAsync("ORD-6", new Money(10m, "EUR"), CancellationToken.None));
    }

    private static HttpClient CreateClient(HttpMessageHandler handler) =>
        new(handler) { BaseAddress = new Uri("https://provider.example.test") };

    private static StringContent JsonContent(string json) =>
        new(json, Encoding.UTF8, "application/json");

    private sealed class StubHttpMessageHandler(Func<HttpRequestMessage, string, HttpResponseMessage> respond) : HttpMessageHandler
    {
        protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
        {
            var body = request.Content is null ? string.Empty : await request.Content.ReadAsStringAsync(cancellationToken);
            return respond(request, body);
        }
    }
}

